@startuml

class InsuranceCompany {}

class Policy {
  + PolicyType : string
}

class CarLiabilityPolicy {
  + CoverageLimit : float
}

class LifePolicy {
  + BeneficiaryName : string
}

class RiskPolicy {
  + RiskFactor : float
}

class Customer {
  + Name : string
  + CustomerId : int
}

class Contract {
  + ContractId : int
  + SigningDate : date
}

InsuranceCompany "1" -- "0..*" Policy
InsuranceCompany "1" -- "0..*" Customer
Customer "1" -- "0..*" Contract
Policy "1" -- "0..*" Contract

CarLiabilityPolicy --|> Policy
LifePolicy --|> Policy
RiskPolicy --|> Policy

@enduml

